const $=s=>document.querySelector(s), game=$('#game');
const nav=(n)=>{render[n]?.()};
let state={car:0,rank:1240,carLevels:[2,3,1,2,2,2]};
const cars=[['FORD FUSION','Redline','R'],['NIGHTSHADE','Street','S'],['VOLT RS','Electric','A']];
function screen(html,cls=''){game.innerHTML=`<div class="screen ${cls}">${html}</div>`}
function pixelCar(color='#d72836'){return `<svg class="pixel-car" viewBox="0 0 320 180" role="img" aria-label="Ford Fusion pixel art"><defs><linearGradient id="g" x2="0" y2="1"><stop stop-color="#ff6670"/><stop offset=".45" stop-color="${color}"/><stop offset="1" stop-color="#780913"/></linearGradient></defs><ellipse cx="160" cy="154" rx="125" rx="125" ry="12" fill="#000" opacity=".7"/><g shape-rendering="crispEdges"><rect x="63" y="91" width="194" height="43" fill="url(#g)"/><rect x="48" y="109" width="223" height="23" fill="#aa1724"/><rect x="94" y="61" width="129" height="36" fill="#bd1d2b"/><rect x="111" y="70" width="44" height="27" fill="#252936"/><rect x="160" y="70" width="46" height="27" fill="#252936"/><rect x="105" y="67" width="53" height="5" fill="#ff7c82"/><rect x="153" y="67" width="55" height="5" fill="#ff7c82"/><rect x="55" y="96" width="209" height="8" fill="#f64250"/><rect x="59" y="119" width="202" height="10" fill="#5d0711"/><rect x="84" y="134" width="42" height="18" fill="#090a10"/><rect x="194" y="134" width="42" height="18" fill="#090a10"/><rect x="89" y="138" width="32" height="14" fill="#363844"/><rect x="199" y="138" width="32" height="14" fill="#363844"/><rect x="94" y="141" width="22" height="8" fill="#11131a"/><rect x="204" y="141" width="22" height="8" fill="#11131a"/><rect x="48" y="103" width="34" height="12" fill="#2a0b10"/><rect x="238" y="103" width="32" height="12" fill="#2a0b10"/><rect x="50" y="106" width="18" height="5" fill="#ffb1b5"/><rect x="252" y="106" width="13" height="5" fill="#ff3a56"/><rect x="153" y="99" width="13" height="31" fill="#810f19"/><rect x="122" y="75" width="4" height="22" fill="#777d8d"/><rect x="176" y="75" width="4" height="22" fill="#777d8d"/></g></svg>`}
const render={
 home(){screen(`<div class="garage-bg"></div><div class="home-logo"><div class="small">NIGHTSHIFT</div><div class="big">SOUND <i>CAR</i></div></div><div class="home-sub">URBAN DIVISION / 01</div><div class="home-menu"><button class="btn primary" onclick="race()"><span>JOGAR</span><span class="menu-icon">▶</span></button><button class="btn" onclick="nav('garage')"><span>GARAGEM</span><span class="menu-icon">▰</span></button><button class="btn" onclick="nav('ranked')"><span>RANQUEADO</span><span class="menu-icon">◆</span></button><button class="btn" onclick="nav('upgrades')"><span>MELHORIAS</span><span class="menu-icon">▲</span></button><button class="btn" onclick="nav('settings')"><span>CONFIGURAÇÕES</span><span class="menu-icon">⚙</span></button></div>`, 'home')},
 garage(){let c=cars[state.car];screen(`<div class="garage-grid"></div><div class="topbar"><button class="back" onclick="nav('home')">‹ VOLTAR</button><div class="title">GARAGEM</div></div><div class="car-stage">${pixelCar(state.car?('#d6d7dc'):'#d72836')}</div><div class="garage-card panel"><div class="garage-card-row"><div><div class="car-name">${c[0]}</div><div class="car-class">${c[1].toUpperCase()} // CLASSE ${c[2]}</div></div><div><button class="arrow" onclick="swapCar(-1)">‹</button> <button class="arrow" onclick="swapCar(1)">›</button></div></div><div class="garage-actions"><button class="btn" onclick="nav('upgrades')">MELHORIAS</button><button class="btn primary" onclick="race()">CORRER</button></div></div>`,'garage')},
 upgrades(){const data=[['Motor','Potência do motor',['◆','⚡','MOTOR']],['Velocidade','Velocidade máxima',['≋','➤','VEL.']],['Aceleração','Tempo de 0–100 km/h',['»','⌁','ACEL.']],['Freios','Distância de frenagem',['■','▥','FREIOS']],['Controle','Estabilidade em curvas',['⌖','◎','CTRL']],['Pneus','Aderência e tração',['●','◉','PNEUS']]];let rows=data.map((d,i)=>`<div class="upgrade-row panel"><div class="ico">${d[2][0]}</div><div><div class="upgrade-name">${d[0]}</div><div class="upgrade-lvl">Nv. ${state.carLevels[i]} / 5 · ${d[1]}</div><div class="bar"><i style="width:${state.carLevels[i]*20}%"></i></div></div><div class="lvlnum">${state.carLevels[i]}</div></div>`).join('');screen(`<div class="topbar"><button class="back" onclick="nav('garage')">‹ VOLTAR</button><div class="title">MELHORIAS</div></div><div class="upgrade-list">${rows}</div><button class="btn primary" style="margin-top:auto;text-align:center;justify-content:center" onclick="nav('garage')">APLICAR AO VEÍCULO</button>`,'upgrades')},
 ranked(){screen(`<div class="topbar"><button class="back" onclick="nav('home')">‹ VOLTAR</button><div class="title">RANQUEADO</div></div><div class="rank-head"><div class="badge"></div><div class="rank-info"><div style="font-size:12px;color:#aaa">DIVISÃO ATUAL</div><div class="points">PRATA II</div><div class="progress"><i></i></div><div style="font-size:11px;margin-top:5px">${state.rank} / 1500 PONTOS</div></div></div><div class="top5 panel"><h3>TOP 5</h3>${[1,2,3,4,5].map(n=>`<div class="empty">${n}  &nbsp;—&nbsp; VAGA DISPONÍVEL</div>`).join('')}</div><div class="rank-actions"><button class="btn primary" onclick="race(true)">JOGAR RANQUEADO</button><button class="btn" onclick="nav('divisions')">DIVISÕES <span>›</span></button></div>`,'ranked')},
 divisions(){const ds=[['Bronze',0,'100','#9b5a3c','Iniciante'],['Prata',1000,'1500','#bfc4ce','Velocidade'],['Ouro',1500,'2000','#d5b24a','Dourado'],['Platina',2000,'2600','#75b7b5','Cromo'],['Diamante',2600,'3200','#9d77ff','Cristal'],['Mestre',3200,'4000','#ff4f72','Elite'],['Lendário',4000,'—','#ffb000','Épico']];let rows=ds.map((d,i)=>`<div class="division-row panel ${i===1?'current':''}"><div class="divbadge" style="--c:${d[3]}"></div><div><div class="divname">${d[0]}</div><div class="divpts">${d[1]} – ${d[2]} PTS</div></div><div class="reward"><b>${d[4]}</b>RECOMPENSA</div></div>`).join('');screen(`<div class="topbar"><button class="back" onclick="nav('ranked')">‹ VOLTAR</button><div class="title">DIVISÕES</div></div><div class="division-list">${rows}</div>`,'divisions')},
 settings(){screen(`<div class="topbar"><button class="back" onclick="nav('home')">‹ VOLTAR</button><div class="title">CONFIGURAÇÕES</div></div><div class="setting-list"><div class="setting panel"><label>Música <span>70%</span></label><input type="range" value="70"></div><div class="setting panel"><label>Efeitos sonoros <span>85%</span></label><input type="range" value="85"></div><div class="setting panel"><label>Qualidade gráfica</label><div class="seg"><button>BAIXA</button><button class="active">ALTA</button><button>ULTRA</button></div></div><div class="setting panel"><label>Controles</label><div class="seg"><button class="active">BOTÕES</button><button>GIROSCÓPIO</button></div></div></div>`,'settings')}
};
function swapCar(d){state.car=(state.car+d+cars.length)%cars.length;render.garage()}
function race(rank=false){screen(`<canvas id="track"></canvas><div class="hud"><div class="hudbox">POS <span id="pos">1</span>/6</div><div class="hudbox" id="time">00:00.00</div></div><div class="controls"><div class="pedals"><button class="ctrl" id="left">◀</button><button class="ctrl" id="right">▶</button></div><button class="ctrl go" id="gas">▲</button></div>`,'race');startRace(rank)}
function startRace(rank=false){const c=$('#track'),ctx=c.getContext('2d');let w=c.width=520,h=c.height=innerHeight;let player={x:260,y:h-150,spd:0,angle:0},others=[{x:210,z:650,color:'#fff'},{x:300,z:770,color:'#26c8d8'},{x:260,z:940,color:'#f0f0b5'}],start=performance.now(),playing=true,keys={};
 function button(id,k){let e=$('#'+id);e.onpointerdown=e=>{e.prevent();keys[k]=true};e.onpointerup=e=>{e.prevent();keys[k]=false};e.onpointercancel=e=>{keys[k]=false}}
 button('left','left');button('right','right');button('gas','gas');
 function loop(t){if(!playing)return;let dt=Math.min(32,t-(loop.old||t))/16.6;loop.old=t;if(keys.gas)player.spd=Math.min(17,player.spd+.25*dt);else player.spd=Math.max(0,player.spd-.11*dt);if(keys.left)player.angle-=.035*dt;if(keys.right)player.angle+=.035*dt;player.angle*=.94;player.x+=Math.sin(player.angle)*player.spd*.24*dt;player.x=Math.max(55,Math.min(w-55,player.x));ctx.fillStyle='#080912';ctx.fillRect(0,0,w,h);ctx.fillStyle='#161526';ctx.fillRect(0,0,w,h);for(let i=0;i<13;i++){let yy=((i*90-player.spd*t*.12)%1170)-250;ctx.fillStyle=i%2?'#25212c':'#1d1d28';ctx.beginPath();ctx.moveTo(w/2+(player.angle*20),yy);ctx.lineTo(w/2+220+(player.angle*20),yy+90);ctx.lineTo(w/2+220+(player.angle*20),yy+130);ctx.lineTo(w/2+(player.angle*20),yy+40);ctx.fill()}ctx.fillStyle='#242331';ctx.beginPath();ctx.moveTo(w/2-310,0);ctx.lineTo(w/2-95,h);ctx.lineTo(w/2+95,h);ctx.lineTo(w/2+310,0);ctx.fill();ctx.strokeStyle='#ff2aa1';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(w/2-310,0);ctx.lineTo(w/2-95,h);ctx.moveTo(w/2+310,0);ctx.lineTo(w/2+95,h);ctx.stroke();ctx.fillStyle='#dbdce4';for(let i=0;i<12;i++){let y=(i*100-(t*player.spd*.5)%1200)-200;if(y>-20&&y<h){ctx.fillRect(w/2-145+(i%2?188:0),y,14,55)}} others.forEach((o,i)=>{o.z-=player.spd*.7;if(o.z<80)o.z=900;o.z=Math.max(80,o.z);let sc=1-o.z/1000, yy=h-o.z*.28, xx=w/2+(o.x-260)*(1-sc*.5);ctx.fillStyle=o.color;ctx.fillRect(xx-18,yy-10,36,20);ctx.fillStyle='#111';ctx.fillRect(xx-22,yy+5,8,12);ctx.fillRect(xx+14,yy+5,8,12)});drawCar(ctx,player.x,player.y,player.angle);let sec=(t-start)/1000,$time=$('#time');$time.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(Math.floor(sec%60)).padStart(2,'0')}.${String(Math.floor((sec%1)*100)).padStart(2,'0')}`;if(sec>25){playing=false;finish(sec)}else requestAnimationFrame(loop)}requestAnimationFrame(loop)
}
function drawCar(ctx,x,y,a){ctx.save();ctx.translate(x,y);ctx.rotate(a*.18);ctx.fillStyle='#090a10';ctx.fillRect(-38,-10,76,58);ctx.fillStyle='#d72836';ctx.fillRect(-32,-18,64,54);ctx.fillRect(-40,-5,80,34);ctx.fillStyle='#ff6370';ctx.fillRect(-30,-17,60,8);ctx.fillStyle='#252936';ctx.fillRect(-22,-12,44,25);ctx.fillStyle='#08090d';ctx.fillRect(-38,26,14,18);ctx.fillRect(24,26,14,18);ctx.fillStyle='#fff1b5';ctx.fillRect(-30,8,9,5);ctx.fillRect(21,8,9,5);ctx.restore()}
function finish(sec){let position=1+Math.floor(Math.random()*3);screen(`<div class="finish-card"><div class="result panel"><div style="font-size:12px;color:#ff62ad">CORRIDA FINALIZADA</div><h2>P${position}º LUGAR</h2><div class="hudbox" style="display:inline-block;margin:10px">${format(sec)}</div><button class="btn primary" onclick="nav('ranked')" style="justify-content:center;margin-top:16px;text-align:center">CONTINUAR</button></div></div>`,'race')}
function format(s){return `00:${String(Math.floor(s)).padStart(2,'0')}.${String(Math.floor((s%1)*100)).padStart(2,'0')}`}
render.home();
